import sqlite3

def q_order(q: str) -> int:
    return {"Q1": 1, "Q2": 2, "Q3": 3, "Q4": 4}.get(q, 999)

def main():
    con = sqlite3.connect("warehouse.db")
    cur = con.cursor()

    # Pull joined revenue/cost by region+quarter and compute profit.
    rows = cur.execute(
        """
        SELECT s.region,
               s.quarter,
               s.revenue,
               c.cost,
               (s.revenue - c.cost) AS profit
        FROM sales s
        JOIN costs c
          ON s.region = c.region
         AND s.quarter = c.quarter
        WHERE s.quarter IN ('Q1','Q2','Q3')
        ORDER BY s.region, s.quarter;
        """
    ).fetchall()

    # Organize by region and quarter order so growth is computed sequentially.
    by_region = {}
    for region, quarter, revenue, cost, profit in rows:
        by_region.setdefault(region, []).append(
            {
                "region": region,
                "quarter": quarter,
                "revenue": revenue,
                "cost": cost,
                "profit": profit,
            }
        )

    out_rows = []
    for region in sorted(by_region.keys()):
        items = sorted(by_region[region], key=lambda r: q_order(r["quarter"]))
        prev_profit = None
        for r in items:
            profit = r["profit"]
            if prev_profit is None:
                growth_abs = None
                growth_pct = None
            else:
                growth_abs = profit - prev_profit
                growth_pct = None if prev_profit == 0 else (profit - prev_profit) / prev_profit
            out_rows.append(
                {
                    "region": region,
                    "quarter": r["quarter"],
                    "profit": profit,
                    "profit_growth_abs": growth_abs,
                    "profit_growth_pct": growth_pct,
                }
            )
            prev_profit = profit

    # Print table (region x quarter profit and growth)
    headers = ["region", "quarter", "profit", "profit_growth_abs", "profit_growth_pct"]

    def fmt(v):
        if v is None:
            return ""
        if isinstance(v, float):
            return f"{v:.15g}"
        return str(v)

    # column widths
    widths = {h: len(h) for h in headers}
    for r in out_rows:
        for h in headers:
            widths[h] = max(widths[h], len(fmt(r[h])))

    print(" | ".join(h.ljust(widths[h]) for h in headers))
    print("-+-".join("-" * widths[h] for h in headers))
    for r in out_rows:
        print(" | ".join(fmt(r[h]).ljust(widths[h]) for h in headers))

    con.close()

if __name__ == "__main__":
    main()

import csv
import math
import re
import sys

import project_profit

# Required output columns (per acceptance criteria)
REQUIRED_COLS = [
    "region",
    "baseline_profit_next_q",
    "projected_profit_next_q",
    "incremental_profit_opportunity",
    "units",
    "method",
    "fallback_applied",
    "note",
]
NUMERIC_COLS = [
    "baseline_profit_next_q",
    "projected_profit_next_q",
    "incremental_profit_opportunity",
    "fallback_applied",
]

TOL = 1e-6


def _isclose(a, b, tol=TOL):
    if math.isnan(a) and math.isnan(b):
        return True
    return abs(a - b) <= tol


def _load_csv(path):
    with open(path, "r", newline="", encoding="utf-8") as f:
        r = csv.DictReader(f)
        if r.fieldnames is None:
            raise AssertionError("CSV has no header")
        missing = [c for c in REQUIRED_COLS if c not in r.fieldnames]
        if missing:
            raise AssertionError(f"Missing required columns: {missing}")
        rows = []
        for row in r:
            parsed = {"region": row["region"]}
            for c in REQUIRED_COLS:
                if c == "region":
                    continue
                parsed[c] = row.get(c, "")
            # numeric checks
            for c in NUMERIC_COLS:
                v = row.get(c, "")
                try:
                    parsed[c] = float(v)
                except Exception:
                    raise AssertionError(
                        f"Non-numeric value for {c} in region={row.get('region')}: {v}"
                    )
            rows.append(parsed)
    return rows


def _expected_from_source():
    expected, _meta = project_profit.compute_projections()
    exp = {}
    for p in expected:
        exp[p.region] = {
            "baseline_profit_next_q": float(p.baseline_profit_next_q),
            "projected_profit_next_q": float(p.projected_profit_next_q),
            "incremental_profit_opportunity": float(p.incremental_profit_opportunity),
            "units": p.units,
            "method": p.method,
            "fallback_applied": float(p.fallback_applied),
            "note": p.note,
        }
    return exp


def _parse_findings_opportunities(findings_text):
    # Parse region incremental opportunities from the markdown table.
    # We look for lines like: | REGION | <number> |
    region_vals = {}
    for line in findings_text.splitlines():
        if not line.strip().startswith("|"):
            continue
        parts = [p.strip() for p in line.strip().strip("|").split("|")]
        if len(parts) < 2:
            continue
        region = parts[0]
        if region.lower() in ("region", "---"):
            continue
        val_txt = parts[1]
        # accept plain floats or formatted with commas
        val_txt = val_txt.replace(",", "")
        if re.fullmatch(r"[-+]?\d*(\.\d+)?", val_txt) and val_txt not in ("", "."):
            region_vals[region] = float(val_txt)

    total = None
    m = re.search(
        r"Total\s+summed\s+incremental\s+profit\s+opportunity\s*[:=]\s*([-+]?\d[\d,]*(?:\.\d+)?)",
        findings_text,
        flags=re.IGNORECASE,
    )
    if m:
        total = float(m.group(1).replace(",", ""))
    return region_vals, total


def main():
    # Regenerate CSV (idempotent) so validation always reflects source-of-truth data.
    projections, _meta = project_profit.compute_projections()
    project_profit.write_csv(projections)

    actual_rows = _load_csv("profit_opportunity_by_region.csv")
    actual = {r["region"]: r for r in actual_rows}

    expected = _expected_from_source()

    if set(actual.keys()) != set(expected.keys()):
        raise AssertionError(
            f"Region set mismatch. expected={sorted(expected.keys())} actual={sorted(actual.keys())}"
        )

    # Validate numeric and string fields match expectations
    for region in sorted(expected.keys()):
        e = expected[region]
        a = actual[region]
        for c in ("baseline_profit_next_q", "projected_profit_next_q", "incremental_profit_opportunity"):
            if not _isclose(float(a[c]), float(e[c])):
                raise AssertionError(f"Mismatch region={region} col={c}: actual={a[c]} expected={e[c]}")
        for c in ("units", "method", "note"):
            if (a[c] or "") != (e[c] or ""):
                raise AssertionError(f"Mismatch region={region} col={c}: actual={a[c]!r} expected={e[c]!r}")
        if not _isclose(float(a["fallback_applied"]), float(e["fallback_applied"])):
            raise AssertionError(
                f"Mismatch region={region} col=fallback_applied: actual={a['fallback_applied']} expected={e['fallback_applied']}"
            )

    # Validate findings.md is consistent with CSV within tolerance
    with open("findings.md", "r", encoding="utf-8") as f:
        txt = f.read()

    findings_region_vals, findings_total = _parse_findings_opportunities(txt)

    if not findings_region_vals:
        raise AssertionError(
            "Could not parse any region incremental opportunities from findings.md markdown table. "
            "Ensure findings.md contains a pipe table with columns: Region | Incremental profit opportunity."
        )

    # Compare regions that appear in findings
    for region, v in findings_region_vals.items():
        if region not in actual:
            raise AssertionError(f"Region {region} appears in findings.md but not in CSV")
        if not _isclose(float(v), float(actual[region]["incremental_profit_opportunity"])):
            raise AssertionError(
                f"findings.md mismatch for region={region}: findings={v} csv={actual[region]['incremental_profit_opportunity']}"
            )

    csv_total = sum(float(r["incremental_profit_opportunity"]) for r in actual_rows)
    if findings_total is None:
        raise AssertionError(
            "Could not parse total summed incremental profit opportunity from findings.md. "
            "Add a line like: Total summed incremental profit opportunity: <number>"
        )
    if not _isclose(float(findings_total), float(csv_total)):
        raise AssertionError(f"Total mismatch: findings={findings_total} csv_sum={csv_total}")

    print("OK: CSV regenerated and validated; findings.md matches CSV within tolerance")


if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        print(f"VERIFY FAILED: {e}", file=sys.stderr)
        sys.exit(1)

