import csv
import sys
from pathlib import Path

REQUIRED_FINDINGS_TOKENS = [
    'Verdict:',
]

REQUIRED_COLS = {
    'variation_id',
    'description',
    'recommended_region',
    'is_same_as_baseline',
    'metric_name',
    'metric_value',
    'ci95_low',
    'ci95_high',
    'recommendation_flag',
}


def fail(msg: str) -> None:
    print(f"VERIFY FAIL: {msg}")
    sys.exit(1)


def load_csv(path: Path) -> list[dict]:
    with path.open('r', encoding='utf-8', newline='') as f:
        reader = csv.DictReader(f)
        if reader.fieldnames is None:
            fail(f'{path.name} has no header row')
        cols = set(reader.fieldnames)
        missing = REQUIRED_COLS - cols
        if missing:
            fail(f"{path.name} missing required columns: {sorted(missing)}")
        rows = list(reader)
    return rows


def main() -> None:
    # Findings
    findings_path = Path('findings.md')
    if not findings_path.exists():
        fail('findings.md does not exist')
    txt = findings_path.read_text(encoding='utf-8')
    if not txt.strip():
        fail('findings.md is empty')
    for tok in REQUIRED_FINDINGS_TOKENS:
        if tok not in txt:
            fail(f"findings.md missing required token: {tok!r}")
    if not any(token in txt for token in ['PASS', 'FAIL']):
        fail("findings.md verdict must include PASS or FAIL")

    # Sensitivity CSV (accept either name)
    candidates = [Path('sensitivity_results.csv'), Path('sensitivity.csv')]
    csv_path = next((p for p in candidates if p.exists()), None)
    if csv_path is None:
        fail('Missing sensitivity_results.csv (or sensitivity.csv)')

    if csv_path.stat().st_size == 0:
        fail(f'{csv_path.name} is empty')

    rows = load_csv(csv_path)
    if len(rows) < 3:
        fail(f'{csv_path.name} must have >=3 modeling variations; found {len(rows)}')

    # Basic type sanity for key numeric fields
    for i, r in enumerate(rows, start=1):
        for key in ['metric_value', 'ci95_low', 'ci95_high']:
            try:
                float(r[key])
            except Exception:
                fail(f"Row {i} column {key} is not parseable as float: {r[key]!r}")

    print('VERIFY OK')


if __name__ == '__main__':
    main()

import csv
import os
import subprocess
import sys

REQUIRED_FILES = [
    "findings.md",
    "robustness_checks.py",
    "robustness_results.csv",
    "verify_robustness.py",
]

REQUIRED_COLUMNS = [
    "check_name",
    "model_spec",
    "metric",
    "estimate",
    "ci_low",
    "ci_high",
    "decision",
    "passed",
]


def _fail(msg: str) -> int:
    print(f"FAIL: {msg}")
    return 1


def _pass(msg: str) -> None:
    print(f"PASS: {msg}")


def main() -> int:
    rc = 0

    # 1) Required files exist and non-empty
    for p in REQUIRED_FILES:
        if not os.path.exists(p):
            rc = 1
            print(f"FAIL: missing required file: {p}")
        elif os.path.getsize(p) <= 0:
            rc = 1
            print(f"FAIL: empty required file: {p}")
        else:
            _pass(f"file present: {p}")

    if rc != 0:
        print("FINAL VERDICT: FAIL")
        return rc

    # 2) robustness_checks.py runs and produces robustness_results.csv
    proc = subprocess.run([sys.executable, "robustness_checks.py"], capture_output=True, text=True)
    if proc.returncode != 0:
        print(proc.stdout)
