from pathlib import Path

REQUIRED_FINDINGS_TOKENS = [
    "Verdict:",
    "Baseline recommendation",
]

REQUIRED_COLS = {
    "variation_id",
    "description",
    "recommended_region",
    "is_same_as_baseline",
    "metric_name",
    "metric_value",
    "ci95_low",
    "ci95_high",
    "oos_metric_name",
    "oos_metric_value",
    "recommendation_flag",
}


def fail(msg: str) -> None:
    print(f"VERIFY FAIL: {msg}")
    sys.exit(1)


def load_csv(path: Path) -> list[dict]:
    with path.open("r", encoding="utf-8", newline="") as f:
        reader = csv.DictReader(f)
        if reader.fieldnames is None:
            fail(f"{path.name} has no header row")
        cols = set(reader.fieldnames)
        missing = REQUIRED_COLS - cols
        if missing:
            fail(f"{path.name} missing required columns: {sorted(missing)}")
        rows = list(reader)
    return rows


def parse_verdict(findings_text: str) -> str:
    # Expect a line like: "Verdict: PASS" or "Verdict: FAIL"
    for line in findings_text.splitlines():
        if "Verdict:" in line:
            u = line.upper()
            if "PASS" in u:
                return "PASS"
            if "FAIL" in u:
                return "FAIL"
    fail("Could not parse Verdict: PASS/FAIL from findings.md")


def main() -> None:
    findings_path = Path("findings.md")
    if not findings_path.exists():
        fail("findings.md does not exist")
    txt = findings_path.read_text(encoding="utf-8")
    if not txt.strip():
        fail("findings.md is empty")
    for tok in REQUIRED_FINDINGS_TOKENS:
        if tok not in txt:
            fail(f"findings.md missing required token: {tok!r}")

    verdict_md = parse_verdict(txt)

    csv_path = Path("sensitivity_results.csv")
    if not csv_path.exists():
        fail("Missing sensitivity_results.csv; run: python robustness_checks.py")
    if csv_path.stat().st_size == 0:
        fail("sensitivity_results.csv is empty")

    rows = load_csv(csv_path)
    if len(rows) < 3:
        fail(f"sensitivity_results.csv must have >=3 modeling variations; found {len(rows)}")

    # Ensure baseline present
    baseline_rows = [r for r in rows if r["variation_id"] == "baseline_ols_all"]
    if len(baseline_rows) != 1:
        fail("Expected exactly one baseline row with variation_id=baseline_ols_all")
    baseline_region = baseline_rows[0]["recommended_region"]

    # Type sanity + flip rate
    flips = 0
    for i, r in enumerate(rows, start=1):
        for key in ["metric_value", "ci95_low", "ci95_high", "oos_metric_value"]:
            try:
                float(r[key])
            except Exception:
                fail(f"Row {i} column {key} is not parseable as float: {r[key]!r}")
        if r["recommended_region"] != baseline_region:
            flips += 1

    flip_rate = flips / len(rows)
    # PASS definition used by findings.md should match:
    # Robust if <=25% variants flip (i.e., stability >=75%).
    verdict_csv = "PASS" if flip_rate <= 0.25 else "FAIL"

    if verdict_md != verdict_csv:
        fail(
            f"Verdict mismatch: findings.md={verdict_md} but sensitivity_results.csv implies {verdict_csv} "
            f"(flip_rate={flip_rate:.3f}, flips={flips}, n={len(rows)})"
        )

    print("VERIFY OK")


if __name__ == "__main__":
    main()

