def fail(msg: str) -> None:
    print(f"VERIFY FAIL: {msg}")
    raise SystemExit(1)


def load_csv(path: Path) -> list[dict]:
    with path.open("r", encoding="utf-8", newline="") as f:
        r = csv.DictReader(f)
        return list(r)


def main() -> int:
    root = Path(".")
    findings = root / "findings.md"
    if not findings.exists() or findings.stat().st_size == 0:
        fail("findings.md missing or empty")
    txt = findings.read_text(encoding="utf-8")
    for tok in REQUIRED_FINDINGS_TOKENS:
        if tok not in txt:
            fail(f"findings.md missing required token: {tok}")

    results_path = root / "robustness_results.csv"
    folds_path = root / "robustness_folds.csv"
    if not results_path.exists():
        fail("robustness_results.csv missing")
    if not folds_path.exists():
        fail("robustness_folds.csv missing")

    results = load_csv(results_path)
    if len(results) == 0:
        fail("robustness_results.csv empty")

    required_cols = {
        "model_spec",
        "description",
        "recommended_region",
        "is_placebo",
        "effect_estimate",
        "effect_se",
        "ci95_low",
        "ci95_high",
        "delta_vs_primary",
    }
    if set(results[0].keys()) != required_cols:
        missing = required_cols - set(results[0].keys())
        extra = set(results[0].keys()) - required_cols
        fail(f"robustness_results.csv columns mismatch; missing={missing} extra={extra}")

    specs = [r["model_spec"] for r in results]
    non_placebo_specs = [r["model_spec"] for r in results if r["is_placebo"].lower() in ("false", "0", "no")]
    if len(set(non_placebo_specs)) < 3:
        fail("Need at least 3 distinct non-placebo model specifications")

    # Must include placebo/permutation-style check
    placebo_rows = [r for r in results if r["is_placebo"].lower() in ("true", "1", "yes")]
    if len(placebo_rows) < 1:
        fail("Need at least one placebo row in robustness_results.csv")

    # Placebo should be near zero relative to main effect
    primary = next((r for r in results if r["model_spec"] == "baseline_ols_all"), None)
    if primary is None:
        fail("Primary spec baseline_ols_all missing")
    primary_eff = float(primary["effect_estimate"])
    placebo_eff = float(placebo_rows[0]["effect_estimate"])
    if abs(placebo_eff) > max(1e-6, 0.2 * abs(primary_eff)):
        fail(f"Placebo effect not near zero vs primary (placebo={placebo_eff}, primary={primary_eff})")

    # Folds requirements
    folds = load_csv(folds_path)
    if len(folds) == 0:
        fail("robustness_folds.csv empty")
    required_fold_cols = {
        "model_spec",
        "fold",
        "seed",
        "baseline_region",
        "pred_next_profit",
        "y_true",
        "mae",
    }
    if set(folds[0].keys()) != required_fold_cols:
        missing = required_fold_cols - set(folds[0].keys())
        extra = set(folds[0].keys()) - required_fold_cols
        fail(f"robustness_folds.csv columns mismatch; missing={missing} extra={extra}")

    folds_by_spec: dict[str, set[str]] = {}
    for r in folds:
        folds_by_spec.setdefault(r["model_spec"], set()).add(r["fold"])

    for spec in set(non_placebo_specs):
        if spec not in folds_by_spec:
            fail(f"Spec {spec} missing from robustness_folds.csv")
        if len(folds_by_spec[spec]) < 5:
            fail(f"Spec {spec} has <5 folds in robustness_folds.csv")

    print("VERIFY OK")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

