            return True, p
    return False, ""


def main() -> int:
    # --- findings.md must exist and be non-empty
    if not _file_nonempty("findings.md"):
        return _fail("findings.md missing or empty")
    _pass("findings.md present and non-empty")

    # --- single-command runner must exist (we don't enforce exact name elsewhere)
    ok_runner, runner_path = _require_any(
        ["robustness_runner.py", "run_robustness.py"], "runner"
    )
    if not ok_runner:
        return _fail("Missing robustness runner (expected robustness_runner.py or run_robustness.py)")
    _pass(f"runner present: {runner_path}")

    # --- robustness results CSV (must include uncertainty columns)
    ok_results, results_path = _require_any(
        ["robustness_results.csv", "robustness_results_summary.csv"], "robustness results"
    )
    if not ok_results:
        return _fail("Missing robustness results CSV (expected robustness_results.csv)")

    header = _read_csv_header(results_path)
    required_results_cols = {
        "model_spec",
        "effect_estimate",
        # uncertainty must be present as either CI columns or SE
    }
    if not required_results_cols.issubset(set(header)):
        return _fail(
            f"{results_path} missing required columns. Have={header}, need_at_least={sorted(required_results_cols)}"
        )
    if not ({"ci95_low", "ci95_high"}.issubset(set(header)) or ("effect_se" in header)):
        return _fail(
            f"{results_path} must include uncertainty columns: either ci95_low/ci95_high or effect_se"
        )
    _pass(f"robustness results CSV schema OK: {results_path}")

    # --- robustness checks CSV (sprint-2 summary)
    ok_checks, checks_path = _require_any(
        ["robustness_checks.csv", "robustness_results.csv"], "robustness checks"
    )
    if not ok_checks:
        return _fail("Missing robustness checks CSV (expected robustness_checks.csv)")

    required_checks_cols = {
        "variant_id",
        "modeling_choice",
        "metric_name",
        "baseline_value",
        "variant_value",
        "delta",
        "decision_flip",
        "recommendation_outcome",
    }
    checks_header = _read_csv_header(checks_path)
    if not required_checks_cols.issubset(set(checks_header)):
        return _fail(
            f"{checks_path} missing required columns. Have={checks_header}, need={sorted(required_checks_cols)}"
        )
    _pass(f"robustness checks CSV schema OK: {checks_path}")

    # --- out-of-sample validation file
    ok_cv, cv_path = _require_any(
        ["robustness_folds.csv", "cv_metrics.csv", "robustness_folds_summary.csv"],
        "validation metrics",
    )
    if not ok_cv:
        return _fail("Missing out-of-sample validation metrics file (expected robustness_folds.csv or cv_metrics.csv)")

    cv_header = _read_csv_header(cv_path)
    if "model_spec" not in cv_header:
        return _fail(f"{cv_path} missing 'model_spec' column")
    if not ("rmse" in cv_header or "mae" in cv_header):
        return _fail(f"{cv_path} must include rmse and/or mae column")
    _pass(f"validation metrics CSV schema OK: {cv_path}")

    # --- findings must reference artifact filenames (and be non-empty)
    with open("findings.md", "r", encoding="utf-8") as f:
        findings = f.read()
    if "robustness_results.csv" not in findings and "robustness_checks.csv" not in findings:
        return _fail("findings.md does not reference robustness_results.csv or robustness_checks.csv")
    if "robustness_folds.csv" not in findings and "cv_metrics.csv" not in findings:
        return _fail("findings.md does not reference robustness_folds.csv or cv_metrics.csv")
    _pass("findings.md references robustness and validation artifact filenames")

    # --- Runner should execute successfully (regenerate artifacts)
    # Keep it simple: just run the runner we found.
    proc = subprocess.run([sys.executable, runner_path])
    if proc.returncode != 0:
        return _fail(f"runner failed: {runner_path} exit={proc.returncode}")
    _pass("runner executes successfully")

    return 0


if __name__ == "__main__":
    raise SystemExit(main())

